import { stages, graph, validateData, layoutGraph } from './atlas-kit.js';
const $=s=>document.querySelector(s);const chart=$('#chart');const numbers=new Intl.NumberFormat('en-US');const percent=(v,d)=>d?`${(v/d*100).toFixed(1)}%`:'—';
let variant='branching', texture='mixed', codeMode='react', pinned=null;const examples={branching:structuredClone(graph),continuous:structuredClone(stages),vertical:structuredClone(stages)};const defaults=structuredClone(examples);let options={texture:'mixed',density:7,curve:.5,strokeWidth:1,labels:true};
const metadata={branching:{no:'003',title:'Branching funnel',subtitle:'Trace acquisition channels through signup and activation.',caption:'03 / Channel paths · quantities proportional to ribbon width'},continuous:{no:'001',title:'Continuous funnel',subtitle:'Follow the same cohort across a smooth sequence of conversion steps.',caption:'01 / Cohort progression · height proportional to remaining visitors'},vertical:{no:'002',title:'Vertical funnel',subtitle:'Compare conversion one stage at a time, from entry to outcome.',caption:'02 / Staged conversion · width proportional to remaining visitors'}};
function inspect(info,locked=false){if(!info)return;$('#inspect-status').textContent=locked?'PINNED PATH':'PATH INSPECTOR';$('#inspect-label').textContent=info.label;$('#inspect-value').textContent=numbers.format(info.value);$('#inspect-conversion').textContent=percent(info.value,info.denominator);$('#inspect-total').textContent=percent(info.value,info.total);$('#clear').hidden=!locked;}
function entries(){if(variant==='branching'){const g=layoutGraph(examples[variant]);return g.links.map(l=>({label:`${l.sourceNode.label} → ${l.targetNode.label}`,value:l.value,denominator:l.sourceNode.value,total:g.total,source:l.source,target:l.target,kind:'link'}));}const data=examples[variant];if(variant==='continuous')return data.slice(0,-1).map((s,i)=>({label:`${s.label} → ${data[i+1].label}`,value:data[i+1].value,denominator:s.value,total:data[0].value,kind:'stage'}));return data.map((s,i)=>({label:s.label,value:s.value,denominator:data[i-1]?.value??s.value,total:data[0].value,kind:'stage'}));}
function table(){const body=$('#comparison-body');body.replaceChildren();entries().forEach(info=>{const row=document.createElement('tr');const cell=document.createElement('td');const btn=document.createElement('button');btn.textContent=info.label;btn.setAttribute('aria-label',`Inspect ${info.label}`);btn.addEventListener('mouseenter',()=>{if(!pinned){chart.highlight(info);inspect(info);}});btn.addEventListener('mouseleave',()=>chart.highlight(pinned));btn.addEventListener('click',()=>{pinned=pinned?.label===info.label?null:info;chart.select(pinned);inspect(info,!!pinned);});cell.append(btn);row.append(cell);[numbers.format(info.value),percent(info.value,info.denominator),percent(info.value,info.total)].forEach(value=>{const td=document.createElement('td');td.textContent=value;row.append(td);});body.append(row);});$('#table-first').textContent=variant==='branching'?'Branch':'Stage';$('#table-note').textContent=variant==='branching'?'Conversion is relative to the source node. “Of total” uses all entry visitors.':'Conversion is relative to the previous stage. “Of total” uses the first stage.';}
function updateCode(){const data=examples[variant];if(codeMode==='react')$('#code').textContent=`import { AtlasFunnel } from './atlas-kit-react';\n\n<AtlasFunnel\n  variant="${variant}"\n  data={${variant==='branching'?'graph':'stages'}}\n  texture="${texture}"\n  density={${options.density}}\n  curve={${options.curve}}\n  strokeWidth={${options.strokeWidth}}\n  labels={${options.labels}}\n  onInspect={(path) => console.log(path)}\n/>`;
 else if(codeMode==='html')$('#code').textContent=`<atlas-funnel id="funnel" variant="${variant}"></atlas-funnel>\n\n<script type="module">\n  import './atlas-kit.js';\n  const funnel = document.querySelector('#funnel');\n  funnel.data = ${variant==='branching'?'graph':'stages'};\n  funnel.options = ${JSON.stringify(options,null,2).replaceAll('\n','\n  ')};\n  funnel.addEventListener('atlas-inspect', ({ detail }) => {\n    console.log(detail);\n  });\n</script>`;
 else $('#code').textContent=JSON.stringify(data,null,2);}
function render(){pinned=null;$('#clear').hidden=true;chart.update(examples[variant],{...options,variant});const m=metadata[variant];$('#figure-no').textContent=`FIG. ${m.no}`;$('#chart-title').textContent=m.title;$('#chart-subtitle').textContent=m.subtitle;$('#caption').textContent=m.caption;document.querySelectorAll('[data-variant]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.variant===variant)));$('#curve').disabled=variant==='vertical';$('#data-editor').value=JSON.stringify(examples[variant],null,2);$('#data-error').textContent='';table();updateCode();inspect(entries()[variant==='branching'?2:0]);}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,2200);}
document.querySelectorAll('[data-variant]').forEach(b=>b.addEventListener('click',()=>{variant=b.dataset.variant;render();}));document.querySelectorAll('[data-texture]').forEach(b=>b.addEventListener('click',()=>{texture=b.dataset.texture;options.texture=texture;document.querySelectorAll('[data-texture]').forEach(el=>{el.classList.toggle('selected',el===b);el.setAttribute('aria-pressed',String(el===b));});render();}));
[['density','density'],['curve','curve'],['stroke','strokeWidth']].forEach(([id,key])=>$('#'+id).addEventListener('input',e=>{options[key]=Number(e.target.value);$('#'+id+'-output').textContent=id==='curve'?options[key].toFixed(2):`${options[key].toFixed(id==='density'?0:1)} px`;render();}));$('#annotations').addEventListener('change',e=>{options.labels=e.target.checked;render();});
$('#reset').addEventListener('click',()=>{options={texture:'mixed',density:7,curve:.5,strokeWidth:1,labels:true};texture='mixed';$('#density').value=7;$('#curve').value=.5;$('#stroke').value=1;$('#density-output').textContent='7 px';$('#curve-output').textContent='0.50';$('#stroke-output').textContent='1.0 px';$('#annotations').checked=true;document.querySelectorAll('[data-texture]').forEach(b=>{b.classList.toggle('selected',b.dataset.texture==='mixed');b.setAttribute('aria-pressed',String(b.dataset.texture==='mixed'));});render();});
chart.addEventListener('atlas-inspect',e=>{if(!pinned)inspect(e.detail);});chart.addEventListener('atlas-select',e=>{pinned=e.detail;if(pinned)inspect(pinned,true);else{$('#clear').hidden=true;$('#inspect-status').textContent='PATH INSPECTOR';}});$('#clear').addEventListener('click',()=>chart.clearSelection());
$('#export').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([chart.exportSVG()],{type:'image/svg+xml'}));const a=document.createElement('a');a.href=url;a.download=`atlas-${variant}.svg`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('SVG exported');});
document.querySelectorAll('[data-code]').forEach(b=>b.addEventListener('click',()=>{codeMode=b.dataset.code;document.querySelectorAll('[data-code]').forEach(el=>el.setAttribute('aria-pressed',String(el===b)));updateCode();}));$('#copy-code').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('#code').textContent);toast('Code copied');$('#copy-code').textContent='Copied';setTimeout(()=>$('#copy-code').textContent='Copy code',1800);}catch{toast('Select the code and copy it manually');}});
$('#apply-data').addEventListener('click',()=>{try{const data=JSON.parse($('#data-editor').value);validateData(data,variant);if(variant==='branching')layoutGraph(data);examples[variant]=data;render();toast('Example updated');}catch(e){$('#data-error').textContent=e.message;}});$('#restore-data').addEventListener('click',()=>{examples[variant]=structuredClone(defaults[variant]);render();toast('Example restored');});render();
